    };
    var CH = ['var(--ch1)','var(--ch2)','var(--ch3)','var(--ch4)','var(--ch5)','var(--ch6)','var(--ch7)','var(--ch8)'];
    var typeOf = function(v){ for (var i=0;i<PR.types.length;i++) if (PR.types[i].v===v) return PR.types[i]; return {v:v,l:v||'—',k:'cfg',d:''}; };
    var hdrLabel = function(h){ h=String(h||'').toLowerCase(); for (var i=0;i<PR.hdrs.length;i++) if (PR.hdrs[i][0]===h) return PR.hdrs[i][1]; return h; };
    var verLt = function(a,b){ a=String(a||'').replace(/^v/i,''); if(!/^\d+\.\d+/.test(a)) return false; var x=a.split('.').map(Number), y=b.split('.').map(Number); for (var i=0;i<3;i++){ var p=x[i]||0,q=y[i]||0; if(p<q) return true; if(p>q) return false; } return false; };
    var fmtN = function(n){ return String(Math.round(n||0)).replace(/\B(?=(\d{3})+(?!\d))/g,' '); };
    var fmtTs = function(ts){ if(!ts) return '—'; var d=new Date(ts*1000); var p=function(x){return (x<10?'0':'')+x;}; return p(d.getDate())+'.'+p(d.getMonth()+1)+' '+p(d.getHours())+':'+p(d.getMinutes()); };
    var ago = function(ts){ var s=Math.max(0,Math.floor(Date.now()/1000-ts)); if(s<90) return 'только что'; if(s<3600) return Math.round(s/60)+' мин назад'; if(s<86400) return Math.round(s/3600)+' ч назад'; return fmtTs(ts); };
    var clone = function(o){ return JSON.parse(JSON.stringify(o)); };
    var cfgJson = function(){ return JSON.stringify(S.cfg); };
