    function newRule(){ return {name:'Новое правило', enabled:true, operator:'AND', conditions:[], responseType:'XRAY_BASE64'}; }
    function unknownKeys(c){ var out=[]; if (!c||typeof c!=='object') return out; Object.keys(c).forEach(function(k){ if (['version','settings','rules'].indexOf(k)<0) out.push(k); }); if (c.settings&&typeof c.settings==='object') Object.keys(c.settings).forEach(function(k){ if (k!=='disableSubscriptionAccessByPath') out.push('settings.'+k); }); (Array.isArray(c.rules)?c.rules:[]).forEach(function(r,i){ if(!r||typeof r!=='object') return; Object.keys(r).forEach(function(k){ if (['name','description','enabled','operator','conditions','responseType','responseModifications'].indexOf(k)<0) out.push('rules['+i+'].'+k); }); (Array.isArray(r.conditions)?r.conditions:[]).forEach(function(x,j){ if(!x||typeof x!=='object') return; Object.keys(x).forEach(function(k){ if (['headerName','operator','value','caseSensitive'].indexOf(k)<0) out.push('rules['+i+'].conditions['+j+'].'+k); }); }); if (r.responseModifications&&typeof r.responseModifications==='object') Object.keys(r.responseModifications).forEach(function(k){ if (!(k in PR.modMin)) out.push('rules['+i+'].responseModifications.'+k); }); }); return out; }
    function keepExtra(o, src, known){ Object.keys(src).forEach(function(k){ if (known.indexOf(k)<0) o[k]=src[k]; }); return o; }
    function normCfg(c){ c = c && typeof c==='object' ? c : {}; var out = keepExtra({version:'1', settings:{}, rules:[]}, c, ['version','settings','rules']); if (c.settings && typeof c.settings==='object') { if (c.settings.disableSubscriptionAccessByPath===true) out.settings.disableSubscriptionAccessByPath=true; keepExtra(out.settings, c.settings, ['disableSubscriptionAccessByPath']); } (Array.isArray(c.rules)?c.rules:[]).forEach(function(r){ if(!r||typeof r!=='object') return; var o={name:String(r.name||''), enabled:r.enabled!==false, operator:(String(r.operator||'AND').toUpperCase()==='OR'?'OR':'AND'), conditions:[], responseType:String(r.responseType||'')}; if (r.description) o.description=String(r.description); (Array.isArray(r.conditions)?r.conditions:[]).forEach(function(x){ if(!x||typeof x!=='object') return; o.conditions.push(keepExtra({headerName:String(x.headerName||''), operator:String(x.operator||'').toUpperCase(), value:String(x.value==null?'':x.value), caseSensitive:x.caseSensitive!==false}, x, ['headerName','operator','value','caseSensitive'])); }); if (r.responseModifications && typeof r.responseModifications==='object') { var m={}, src=r.responseModifications; Object.keys(src).forEach(function(k){ m[k]=src[k]; }); if (m.headers) m.headers=(Array.isArray(m.headers)?m.headers:[]).map(function(h){ return {key:String(h&&h.key||''), value:String(h&&h.value==null?'':h.value)}; }); if (Object.keys(m).length) o.responseModifications=m; } out.rules.push(keepExtra(o, r, ['name','description','enabled','operator','conditions','responseType','responseModifications'])); }); return out; }

    function condText(c, html){ var t=esc; var app=appOf(c); if (app) return 'приложение <b>'+t(app.label)+'</b>'; var lbl = hdrLabel(c.headerName); var known = PR.hdrs.some(function(h){ return h[0]===c.headerName.toLowerCase(); }); var head = known ? t(lbl) : '<code>'+t(c.headerName)+'</code>'; var isRe = /REGEX/.test(c.operator); var val = isRe ? '<code>'+t(c.value)+'</code>' : '<b>'+t(c.value)+'</b>'; return head+' '+t(PR.ops[c.operator]||c.operator.toLowerCase())+' '+val+(c.caseSensitive?'':' <span class="pr-sub">без учёта регистра</span>'); }
    function ruleWho(r){ if (!r.conditions.length) return 'всем'; var parts=r.conditions.map(function(c){ return condText(c); }); return parts.join(r.operator==='OR' ? ' <span class="pr-sub">или</span> ' : ' <span class="pr-sub">и</span> '); }
    function modChips(r, idx){ var m=r.responseModifications||{}, out=[]; var errs=S.check.errors.filter(function(e){ return e.rule===idx; }); var bad=function(code){ return errs.some(function(e){ return e.code===code; }); }; var vb=function(k){ var min=PR.modMin[k]; return S.ver && min && verLt(S.ver,min) ? ' w' : ''; }; if (m.headers&&m.headers.length) out.push('<span class="pr-m'+(bad('hdr_ascii')||bad('hdr_key')||bad('hdr_val')?' bad':vb('headers'))+'">'+m.headers.length+' '+(m.headers.length===1?'заголовок':(m.headers.length<5?'заголовка':'заголовков'))+(m.applyHeadersToEnd?' · последними':'')+'</span>'); if (m.subscriptionTemplate) out.push('<span class="pr-m'+vb('subscriptionTemplate')+'">шаблон '+esc(m.subscriptionTemplate)+'</span>'); if (m.ignoreHostXrayJsonTemplate) out.push('<span class="pr-m'+vb('ignoreHostXrayJsonTemplate')+'">без шаблона у сервера</span>'); if (m.ignoreServeJsonAtBaseSubscription) out.push('<span class="pr-m'+vb('ignoreServeJsonAtBaseSubscription')+'">оставить base64</span>'); if (m.disableHwidCheck) out.push('<span class="pr-m'+vb('disableHwidCheck')+'">без лимита устройств</span>'); if (m.additionalExtendedClientsRegex&&m.additionalExtendedClientsRegex.length) out.push('<span class="pr-m'+vb('additionalExtendedClientsRegex')+'">расширенные клиенты: '+m.additionalExtendedClientsRegex.length+'</span>'); if (m.encryption&&m.encryption.method) out.push('<span class="pr-m'+vb('encryption')+'">шифрование '+esc(m.encryption.method)+'</span>'); if (m.excludeHostsByTags&&m.excludeHostsByTags.length) out.push('<span class="pr-m'+vb('excludeHostsByTags')+'">скрыть: '+esc(m.excludeHostsByTags.join(', '))+'</span>'); if (m.respondWithRemarks&&m.respondWithRemarks.length) out.push('<span class="pr-m'+((S.st&&!S.st.custom_remarks)?' w':vb('respondWithRemarks'))+'">сообщения вместо серверов</span>'); return out.join(''); }
