    function renderCtx(){ var st=S.st; if(!st){ $('prCtx').innerHTML=''; return; } var p=S.paths||{n:0,apps:[]}; var paths = S.cfg.settings.disableSubscriptionAccessByPath ? '<span class="pr-chip" data-tip="Прямые ссылки /json, /mihomo, /stash, /clash, /singbox отвечают 403"><span class="d off"></span>Ссылки /json, /mihomo: закрыты</span>' : '<span class="pr-chip" data-tip="'+esc(p.n? 'По логу за 30 дн по прямым ссылкам ходили: '+p.apps.map(function(a){return a.name+' ('+a.n+')';}).join(', ')+'. Закроете — они получат 403' : 'За 30 дн по прямым ссылкам /json, /mihomo никто не ходил')+'"><span class="d'+(p.n?' w':'')+'"></span>Ссылки /json, /mihomo: открыты'+(p.n?' · '+fmtN(p.n)+' запросов за 30 дн':'')+'</span>'; $('prCtx').innerHTML = '<span class="pr-chip" data-tip="«Сообщения вместо серверов» сработают только при включённых своих ремарках (настройки подписки панели)"><span class="d'+(st.custom_remarks?'':' off')+'"></span>Свои ремарки: '+(st.custom_remarks?'включены':'выключены')+'</span>' + '<span class="pr-chip" data-tip="Приложениям из списка JSON-клиентов панель отдаёт полный конфиг вместо base64, если правило это не запрещает"><span class="d'+(st.serve_json?'':' off')+'"></span>JSON на базовой ссылке: '+(st.serve_json?'включено':'выключено')+'</span>' + '<span class="pr-chip" data-tip="Проверка лимита устройств в панели"><span class="d'+(st.hwid&&st.hwid.enabled?'':' off')+'"></span>Проверка устройств: '+(st.hwid&&st.hwid.enabled?'включена':'выключена')+'</span>' + paths; }

    function renderIn(){ var el=$('prIn'); if(!S.clients){ el.hidden=true; return; } el.hidden=false; var total=S.clients.total||0; $('prInN').innerHTML = fmtN(total)+'<small>запросов за '+(S.hours===720?'30 дн':'7 дн')+' · '+((S.clients.groups||[]).length-1)+' групп клиентов</small>'; var stack='', leg=''; if (mapValid()){ var m=S.map, tot=m.total||1; S.cfg.rules.forEach(function(r,i){ var st=m.by_rule[i]; if(!st||!st.n) return; var w=st.n/tot*100; stack+='<i style="width:'+w.toFixed(2)+'%;background:'+CH[i%CH.length]+'" data-tip="'+esc((i+1)+' · '+r.name+' · '+fmtN(st.n))+'" data-go="'+i+'"></i>'; }); if (m.none_n) stack+='<i style="width:'+(m.none_n/tot*100).toFixed(2)+'%;background:var(--c-bad-fg)" data-tip="Никуда не попали — 403 · '+fmtN(m.none_n)+'"></i>'; if (m.untested_n) stack+='<i style="width:'+(m.untested_n/tot*100).toFixed(2)+'%;background:var(--line)" data-tip="Новые группы, ещё не проверены · '+fmtN(m.untested_n)+'"></i>'; S.cfg.rules.forEach(function(r,i){ var st=m.by_rule[i]; leg+='<span><i style="background:'+(st&&st.n?CH[i%CH.length]:'var(--line)')+'"></i>'+(i+1)+' '+esc(r.name)+' '+(tot?Math.round((st?st.n:0)/tot*100):0)+'%</span>'; }); leg+='<span><i style="background:var(--c-bad-fg)"></i>403 — '+fmtN(m.none_n||0)+'</span>'; } else { stack='<i style="width:100%;background:var(--line)"></i>'; leg='<span class="pr-sub">Распределение по правилам появится после «Прогнать по клиентам»</span>'; } $('prStack').innerHTML=stack; $('prLeg').innerHTML=leg; var stale=$('prStale'); if (!S.map) stale.innerHTML = S.busyMap ? '<span class="pr-stale"><span class="d"></span>считаю…</span>' : '<span class="pr-stale" style="color:var(--muted)">цифры не считались · <a data-act="map">прогнать по клиентам</a></span>'; else if (!mapValid()) stale.innerHTML='<span class="pr-stale"><span class="d"></span>цифры устарели — черновик изменён · <a data-act="map">пересчитать</a></span>'; else if (S.map.untested && S.map.untested.length) stale.innerHTML='<span class="pr-stale"><span class="d"></span>'+S.map.untested.length+' '+(S.map.untested.length===1?'новая группа клиентов ещё не проверена':(S.map.untested.length<5?'новые группы клиентов ещё не проверены':'новых групп клиентов ещё не проверены'))+' · <a data-act="map">пересчитать</a></span>'; else stale.innerHTML='<span class="pr-stale" style="color:var(--muted)">тестер панели · '+ago(S.map.ts)+'</span>'; }

    function renderGlobalLints(){ var g=[]; S.check.errors.concat(S.check.warnings).forEach(function(e){ if (e.rule===null||e.rule===undefined) g.push(e); }); var h=''; g.forEach(function(e){ var isErr = S.check.errors.indexOf(e)>=0; h+=noteHtml(isErr?'b':'w', noteMsg(e), e.fix); }); if (S.check.unknown&&S.check.unknown.length) h+=noteHtml('i', 'Поля, которых прослойка не знает (их добавила новая версия панели или вы в JSON), уйдут в панель как есть: <code>'+S.check.unknown.map(esc).join('</code>, <code>')+'</code>'); $('prGlint').innerHTML=h; }

    function stepHtml(r, i, ca){ var errs=S.check.errors.filter(function(e){ return e.rule===i; }), warns=S.check.warnings.filter(function(e){ return e.rule===i; }); var st=ruleStat(i); var dead = ca>=0 && i>ca && r.enabled; var synth = !!(st && st.groups && st.groups.some(function(g){ return g.synthetic; })); var zero = mapValid() && r.enabled && !dead && (!st||!st.n) && !synth && i!==ca; var cls='pr-step'+(errs.length?' err':(st&&(st.n||synth)?' hit':''))+(zero?' zero':'')+(!r.enabled?' off':'')+(i===ca?' fb':'')+(dead?' dead':'')+(S.open===i?' open':''); var ty=typeOf(r.responseType); var h='<div class="'+cls+'" data-i="'+i+'" draggable="false">'; h+='<div class="pr-h"><span class="g" draggable="true" data-tip="Перетащить">'+I.grab+'</span><b>'+esc(r.name||'без имени')+'</b><span class="who">'+ruleWho(r)+'</span><span class="arr">→</span><span class="pr-ty '+ty.k+'">'+esc(ty.l)+'</span>'+(i===ca?'<span class="tag normal">последнее</span>':'')+'<span class="act"><button type="button" class="pr-ib" data-act="toggle" data-tip="'+(S.open===i?'Свернуть':'Изменить')+'">'+(S.open===i?I.up:I.edit)+'</button><button type="button" class="pr-ib hm" data-act="dup" data-tip="Дублировать">'+I.dup+'</button><button type="button" class="pr-ib" data-act="mvup" data-tip="Выше">'+I.up+'</button><button type="button" class="pr-ib" data-act="mvdn" data-tip="Ниже">'+I.down+'</button><button type="button" class="pr-ib del" data-act="del" data-tip="Удалить">'+I.del+'</button><label class="switch sm" data-act="en" data-tip="'+(r.enabled?'Включено':'Выключено')+'"><input type="checkbox" tabindex="-1"'+(r.enabled?' checked':'')+'><span class="sl"></span></label></span></div>'; var chips=modChips(r,i); if (chips) h+='<div class="pr-mods">'+chips+'</div>'; errs.forEach(function(e){ h+=noteHtml('b', noteMsg(e), e.fix); }); warns.forEach(function(e){ h+=noteHtml('w', noteMsg(e), e.fix); }); if (dead) h+=noteHtml('i', 'Чтобы правило заработало, перетащите его выше «'+esc(S.cfg.rules[ca].name)+'