    $('prSnapsBody').addEventListener('click', function(ev){ var b=ev.target.closest('[data-snapact]'); if(!b) return; var a=b.dataset.snapact, id=b.dataset.id; if (a==='add') { var note=($('prSnapNote')&&$('prSnapNote').value||'').trim(); b.disabled=true; post('pr_snap_add', {note:note}).then(function(r){ if(!r.ok){ uiAlert(r.error||'Не удалось'); return; } S.snaps=r.snaps; renderSnaps(); uiToast('Снимок сохранён'); }); return; } if (a==='dlcur') { dl('panel-rules-current.json', S.st.rules); return; } if (a==='dl') { getj('pr_snap','&id='+id).then(function(r){ if (r.ok) dl('panel-rules-snapshot-'+id+'.json', r.snap.rules); }); return; } if (a==='del') { uiConfirm('Удалить снимок?', function(){ post('pr_snap_del', {id:id}).then(function(r){ S.snaps=r.snaps||S.snaps; renderSnaps(); }); }, 'Удалить', true); return; } if (a==='diff') { var row=b.closest('.pr-s'); var old=row.querySelector('.pr-diff'); if (old) { old.remove(); return; } getj('pr_snap','&id='+id).then(function(r){ if(!r.ok) return; var d=diffCfg(r.snap.rules, S.st.rules); var h='<div class="pr-diff"><div class="pr-sub">Снимок → то, что в панели сейчас'+(isDirty()?' (без ваших неотправленных правок)':'')+':</div>'; d.added.forEach(function(n){ h+='<div class="pr-dl p"><span class="k">+</span><b>'+esc(n)+'</b><span class="m2">есть в панели, нет в снимке</span></div>'; }); d.removed.forEach(function(n){ h+='<div class="pr-dl m"><span class="k">−</span><b>'+esc(n)+'</b><span class="m2">есть в снимке, в панели нет</span></div>'; }); d.changed.forEach(function(c){ h+='<div class="pr-dl c"><span class="k">~</span><b>'+esc(c.name)+'</b><span class="m2">'+esc(c.fields.join('; '))+'</span></div>'; }); if (d.settings) h+='<div class="pr-dl c"><span class="k">~</span><b>настройки</b><span class="m2">закрытие ссылок /json</span></div>'; if (!d.added.length&&!d.removed.length&&!d.changed.length&&!d.settings) h+='<div class="pr-dl"><span class="k">=</span><span class="m2">отличий нет</span></div>'; h+='</div>'; row.insertAdjacentHTML('beforeend', h); }); return; } if (a==='restore') { uiConfirm('Отправить этот снимок в панель вместо текущих правил? Текущие правила панели перед этим сохранятся отдельным снимком.', function(){ S.busy=true; post('pr_snap_restore', {id:id, base_hash:S.baseHash}).then(function(r){ S.busy=false; if (r.conflict) { uiAlert('В панели правила изменились с момента открытия вкладки. Перезагрузите вкладку и повторите.'); return; } if (!r.ok) { uiAlert(r.error||'Не удалось'); return; } applyState(r.state); S.snaps=r.snaps||S.snaps; renderSnaps(); uiToast('Снимок восстановлен в панели'); }); }, 'Восстановить', false); return; } });

    // ---------- проверка одним запросом ----------
    function openTester(ruleIdx){ var g=(S.clients&&S.clients.groups)||[]; var opts=''; g.forEach(function(x){ if (x.synthetic) return; opts+='<option value="cl:'+esc(x.id)+'">'+esc(x.name)+(x.os?' · '+esc(osLbl(x.os)):'')+' · '+fmtN(x.n)+' за период</option>'; }); opts+='<option value="browser">Браузер (типовой UA)</option><optgroup label="Из каталога">'; PR.apps.forEach(function(a){ opts+='<option value="app:'+esc(a.key)+'">'+esc(a.label)+'</option>'; }); opts+='</optgroup><option value="custom">Свой User-Agent…</option>'; $('prTestBody').innerHTML='<div class="pr-sub" style="margin-bottom:.6rem">Прослойка отправляет черновик в тестер панели вместе с заголовками ниже и показывает, какое правило сработало бы. В панель ничего не сохраняется.</div><div class="pr-tst"><div class="pr-tf"><label>Приложение</label><div class="two"><select id="prTApp">'+opts+'</select><input type="text" id="prTUa" placeholder="User-Agent"></div><div class="pr-hint" id="prTHint"></div><label>Устройство</label><div class="two"><select id="prTOs"><option value="">— не слать ОС —</option><option>Android</option><option>iOS</option><option>Windows</option><option>macOS</option><option>Linux</option></select><input type="text" id="prTHw" placeholder="x-hwid (пусто — не слать)"></div><label>Пользователь (shortUuid)</label><input type="text" id="prTShort" placeholder="Нужен для правил по ссылке подписки" style="width:100%"><label>Ещё заголовки</label><div id="prTHx"></div><button type="button" class="pr-add" id="prTAddH" style="margin-top:.4rem">'+I.plus+' заголовок</button><div style="margin-top:.8rem"><button type="button" class="pr-prim" id="prTRun">Проверить</button></div></div><div class="pr-res" id="prTRes"><div class="pr-sub">Нажмите «Проверить».</div></div></div>'; $('prTest').classList.add('open'); var sel=$('prTApp'); var fill=function(){ var v=sel.value; $('prTHint').innerHTML=''; if (v.indexOf('cl:')===0) { var x=g.filter(function(y){ return y.id===v.slice(3); })[0]; if (x) { $('prTUa').value=x.ua; $('prTOs').value=(x.dv&&x.dv.o)||''; $('prTHw').value=x.hwid?'submw-test-'+x.id.replace(/[^A-Za-z0-9]/g,'').slice(0,12)+'000000':''; $('prTHint').innerHTML=I.info+'<span>Настоящий User-Agent и заголовки устройства из последнего запроса этого клиента в прослойку.</span>'; } } else if (v==='browser') { $('prTUa').value='Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/130.0.0.0 Safari/537.36'; $('prTOs').value=''; $('prTHw').value=''; $('prTHint').innerHTML=I.info+'<span>Будет отправлен Accept: text/html — как браузер.</span>'; } else if (v.indexOf('app:')===0) { var a=PR.apps.filter(function(y){ return y.key===v.slice(4); })[0]; if (a) { $('prTUa').value=a.pre+'1.0'; $('prTOs').value=''; $('prTHw').value=''; } } else { $('prTUa').value=''; $('prTUa').focus(); } }; sel.addEventListener('change', fill); fill(); $('prTAddH').addEventListener('click', function(){ $('prTHx').insertAdjacentHTML('beforeend','<div class="pr-hx"><input type="text" placeholder="cf-ipcountry"><input type="text" placeholder="DE"><button type="button" class="pr-ib del" onclick="this.parentNode.remove()">'+I.x+'</button></div>'); }); $('prTRun').addEventListener('click', function(){ var hdr={'user-agent':$('prTUa').value}; if ($('prTApp').value==='browser') hdr.accept='text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8'; if ($('prTOs').value) hdr['x-device-os']=$('prTOs').value; if ($('prTHw').value) hdr['x-hwid']=$('prTHw').value; if ($('prTShort').value.trim()) hdr['x-remnawave-injected-short-uuid']=$('prTShort').value.trim(); $('prTHx').querySelectorAll('.pr-hx').forEach(function(row){ var i=row.querySelectorAll('input'); if (i[0].value.trim()) hdr[i[0].value.trim()]=i[1].value; }); $('prTRes').innerHTML='<div class="pr-sub">спрашиваю панель…</div>'; var t0=Date.now(); post('pr_test', {cfg:cfgJson(), headers:JSON.stringify(hdr)}).then(function(r){ var ms=Date.now()-t0; if (!r.ok) { $('prTRes').innerHTML='<div class="ok"><div class="ic bad">'+I.x+'</div><div><b>Не удалось</b><div class="s">'+esc(r.error||'')+'</div></div></div>'; return; } var h=''; if (r.matched && r.idx!=null) { var rule=S.cfg.rules[r.idx]; var ty=typeOf(r.type); h+='<div class="ok"><div class="ic">'+I.ok+'</div><div><b>Сработает «'+esc(rule?rule.name:r.name)+'» (№'+(r.idx+1)+')</b><div class="s">Ответ: '+esc(ty.l)+'</div></div></div>'; if (ruleIdx!=null && ruleIdx!==r.idx) h+='<div class="pr-note w">'+I.warn+'<span>Проверяли правило №'+(ruleIdx+1)+', а первым подошло №'+(r.idx+1)+' — оно стоит выше и перехватывает этот запрос.</span></div>'; var m=rule&&rule.responseModifications||{}; h+='<table>'; var oh=Object.keys(r.headers||{}); h+='<tr><td>Заголовки от правила</td><td>'+(oh.length?oh.map(function(k){ return '<code>'+esc(k)+'</code>'; }).join(', '):'—')+'</td></tr>'; if (m.subscriptionTemplate) h+='<tr><td>Шаблон</td><td>'+esc(m.subscriptionTemplate)+'</td></tr>'; if (m.disableHwidCheck) h+='<tr><td>Лимит устройств</td><td>не проверяется</td></tr>'; if (m.respondWithRemarks) h+='<tr><td>Вместо серверов</td><td>'+m.respondWithRemarks.length+' строк'+(S.st&&!S.st.custom_remarks?' · <span style="color:var(--c-warn-fg)">свои ремарки выключены — не сработает</span>':'')+'</td></tr>'; h+='</table>'; } else { h+='<div class="ok"><div class="ic bad">'+I.x+'</div><div><b>Ни одно правило не подошло</b><div class="s">Панель ответит 403 (через страницу подписки — обрыв соединения)</div></div></div>'; } h+='<div class="pr-sub" style="margin-top:.6rem">Тестер не учитывает подмену base64 → JSON на базовой ссылке и поведение страницы подписки.</div><div class="src">Проверено тестером панели '+esc(S.ver||'')+' · '+ms+' мс</div>'; $('prTRes').innerHTML=h; }); }); }
    $('prTestBtn').addEventListener('click', function(){ openTester(null); });

    // ---------- карта клиентов ----------
    function runMap(cachedOnly){ if (!S.cfg || (S.busyMap && !cachedOnly)) return; if (PR.scopes.tester==='miss') { if (!cachedOnly) uiAlert('У API-токена нет права system:test-srr-matcher — добавьте его в панели и проверьте права на вкладке «Подключение».'); return; } if (!cachedOnly) S.busyMap=true; var j=cfgJson(); renderIn(); post('pr_map', {cfg:j, hours:S.hours, cached:cachedOnly?'1':'', force:(!cachedOnly&&S.map&&S.mapCfg===j&&!(S.map.untested&&S.map.untested.length))?'1':''}).then(function(r){ if (!cachedOnly) S.busyMap=false; if (cachedOnly && S.map && S.mapCfg!==j) return; if (!r.ok) { if (!r.nocache && !cachedOnly) uiAlert(r.error||'Не удалось'); render(); return; } S.map=r; S.mapCfg=j; S.mapStale=false; render(); if (r.warn && !cachedOnly) uiToast(r.warn); }); }
    $('prMapBtn').addEventListener('click', function(){ runMap(false); });
    $('prHours').addEventListener('click', function(ev){ var b=ev.target.closest('[data-h]'); if(!b) return; S.hours=parseInt(b.dataset.h,10); $('prHours').querySelectorAll('button').forEach(function(x){ x.classList.toggle('on', x===b); }); getj('pr_clients','&hours='+S.hours).then(function(r){ if(!r.ok) return; S.clients=r; S.presence=r.presence; S.map=null; render(); runMap(true); }); });

    // ---------- JSON ----------
    $('prView').addEventListener('click', function(ev){ var b=ev.target.closest('[data-v]'); if(!b) return; S.view=b.dataset.v; $('prView').querySelectorAll('button').forEach(function(x){ x.classList.toggle('on', x===b); }); $('prWf').hidden = S.view!=='wf'; $('prJson').hidden = S.view!=='json'; if (S.view==='json') { $('prJsonTa').value=JSON.stringify(S.cfg, null, 2); jsonStatus(); } });
    function jsonStatus(){ var st=$('prJsonSt'); try { var o=JSON.parse($('prJsonTa').value); var n=normCfg(o); var u=unknownKeys(o); st.className='st '+(u.length?'bad':'ok'); st.innerHTML=(u.length?I.warn:I.ok)+' JSON разобран · '+n.rules.length+' правил'+(u.length?' · будут выброшены поля: '+esc(u.slice(0,6).join(', '))+(u.length>6?'…':''):''); return n; } catch(e){ st.className='st bad'; st.innerHTML=I.x+' '+esc(String(e.message||e).slice(0,120)); return null; } }
    $('prJsonTa').addEventListener('input', jsonStatus);
    $('prJsonApply').addEventListener('click', function(){ var n=jsonStatus(); if(!n) return; S.cfg=n; S.open=-1; touch(); uiToast('Черновик обновлён из JSON'); });
    $('prJsonDl').addEventListener('click', function(){ dl('panel-rules-draft.json', S.cfg); });
    $('prJsonFile').addEventListener('click', function(){ $('prJsonInput').click(); });
    $('prJsonInput').addEventListener('change', function(){ var f=this.files&&this.files[0]; if(!f) return; var rd=new FileReader(); rd.onload=function(){ $('prJsonTa').value=String(rd.result||''); jsonStatus(); }; rd.readAsText(f); this.value=''; });

    // ---------- отправка ----------
    function applyState(st){ if (!st) return; S.st=st; S.base=normCfg(st.rules||{}); S.cfg=clone(S.base); S.baseHash=st.hash||''; S.open=-1; S.sel=null; S.map=null; S.mapCfg=''; render(); runCheck(); runMap(true); }
    $('prRevert').addEventListener('click', function(){ uiConfirm('Отменить все неотправленные правки и вернуться к тому, что в панели?', function(){ S.cfg=clone(S.base); S.open=-1; touch(); }, 'Отменить правки', true); });
    $('prPush').addEventListener('click', function(){ if (!isDirty()) return; var d=diffCfg(S.base, S.cfg); var w=S.check.warnings; var h='<div class="pr-mh"><div class="ic"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 2 11 13"/><path d="M22 2 15 22l-4-9-9-4z"/></svg></div><div><b>Отправить '+S.cfg.rules.length+' правил в панель?</b><div class="s">'+esc(dirtySummary())+'</div></div></div><div style="margin-top:.6rem">'; h+='<div class="pr-stp"><div class="ic ok">'+I.ok+'</div><div><b>Снимок текущих правил панели будет сохранён</b><span class="m2">можно будет восстановить в один клик</span></div></div>'; h+='<div class="pr-stp"><div class="ic ok">'+I.ok+'</div><div><b>Перед отправкой прослойка ещё раз прочитает панель</b><span class="m2">если правила там менялись с момента открытия вкладки — отправка остановится</span></div></div>'; if (w.length) h+='<div class="pr-stp"><div class="ic w">!</div><div><b>'+w.length+' '+(w.length===1?'предупреждение остаётся':(w.length<5?'предупреждения остаются':'предупреждений остаётся'))+'</b><span class="m2">'+esc(w.slice(0,3).map(function(x){ return x.msg; }).join(' · '))+(w.length>3?' · …':'')+'. Панель примет правила, но эти сработают не так, как задумано.</span></div></div>'; if (!S.pushed) h+='<div class="pr-stp"><div class="ic i">i</div><div><b>Это первая отправка из прослойки</b><span class="m2">Пока правила не трогали, панель сама обновляла их при своих обновлениях. После отправки она перестанет это делать — новые правила по умолчанию будут приходить только через примеры здесь.</span></div></div>'; var risky=w.some(function(x){ return x.code==='empty'||x.code==='no_catchall'; }); if (risky) h+='<div class="pr-stp"><div class="ic bad">!</div><div><b>Тем, кто не подойдёт ни под одно правило, панель ответит 403</b><span class="m2">Чтобы отправить так, введите слово <b>ОТПРАВИТЬ</b>:</span><input type="text" id="prPushWord" autocomplete="off" style="margin-top:.4rem;width:100%"></div></div>'; h+='</div><div class="dlg-actions"><button type="button" class="pr-ghost" data-close="prConfirm">Отменить</button><button type="button" class="pr-prim" id="prPushGo"'+(risky?' disabled':'')+'>Отправить</button></div>'; $('prConfirmBody').innerHTML=h; $('prConfirm').classList.add('open'); if (risky) $('prPushWord').addEventListener('input', function(){ $('prPushGo').disabled = this.value.trim().toUpperCase()!=='ОТПРАВИТЬ'; }); $('prPushGo').addEventListener('click', function(){ var b=this; if (risky && $('prPushWord').value.trim().toUpperCase()!=='ОТПРАВИТЬ') return; b.disabled=true; b.textContent='Отправляю…'; S.busy=true; post('pr_push', {cfg:cfgJson(), base_hash:S.baseHash}).then(function(r){ S.busy=false; $('prConfirm').classList.remove('open'); if (r.conflict) { uiConfirm('В панели правила изменились с момента открытия вкладки — отправлять поверх нельзя. Перезагрузить правила из панели? Ваши правки останутся в JSON-копии (скачайте её перед перезагрузкой).', function(){ load(); }, 'Перезагрузить', false); return; } if (!r.ok) { if (r.errors&&r.errors.length) { S.check={errors:r.errors, warnings:r.warnings||[], unknown:[]}; render(); } uiAlert(r.error||'Не удалось отправить'); return; } S.pushed=1; applyState(r.state); getj('pr_snaps').then(function(x){ if (x.ok) { S.snaps=x.snaps; $('prSnapsN').textContent=S.snaps.length||''; } }); uiToast('Правила отправлены в панель'); }); }); });
    window.addEventListener('beforeunload', function(ev){ if (S.cfg && isDirty()) { ev.preventDefault(); ev.returnValue=''; } });

    // ---------- загрузка ----------
    function load(){ $('prSub').textContent='читаю правила из панели…'; $('prWf').innerHTML='<div class="pr-rail"></div><div class="pr-empty">Читаю правила из панели…</div>'; getj('pr_load').then(function(r){ S.ver=r.ver||''; PR.scopes=r.scopes||PR.scopes; S.tags=r.tags||[]; S.templates=r.templates||[]; S.clients=r.clients||null; S.presence=r.presence||null; S.paths=r.paths||null; S.snaps=r.snaps||[]; S.pushed=r.pushed||0; $('prSnapsN').textContent=S.snaps.length||''; var ro=$('prRo'); if (PR.scopes.update==='miss' || PR.scopes.tester==='miss') { ro.hidden=false; var parts=[]; if (PR.scopes.update==='miss') parts.push('нет права <code>subscription-settings:update</code> — правила видно, но отправить их в панель нельзя'); if (PR.scopes.tester==='miss') parts.push('нет права <code>system:test-srr-matcher</code> — проверка черновика и карта клиентов недоступны'); $('prRoText').innerHTML='У API-токена '+parts.join('; ')+'. Добавьте права токену в панели и проверьте их снова.'; } else ro.hidden=true; if (!r.ok) { $('prSub').textContent='панель недоступна'; $('prWf').innerHTML='<div class="pr-rail"></div><div class="pr-empty">Не удалось прочитать правила из панели: '+esc(r.error||'')+'<br><button type="button" class="pr-ghost" style="margin-top:.6rem" onclick="location.reload()">Попробовать снова</button></div>'; return; } if (r.check) S.check={errors:r.check.errors||[], warnings:r.check.warnings||[], unknown:r.check.unknown||[]}; S.loaded=true; applyState(r.state); }); }
    $('prAdd').addEventListener('click', function(){ var ca=catchAllIdx(); var at = ca>=0 ? ca : S.cfg.rules.length; S.cfg.rules.splice(at,0,newRule()); S.open=at; S.step=1; touch(); var el=document.querySelector('.pr-step[data-i="'+at+'"]'); if (el) { el.scrollIntoView({behavior:'smooth', block:'center'}); var inp=el.querySelector('[data-f="name"]'); if (inp) { inp.focus(); inp.select(); } } });
    document.querySelectorAll('#prRoot .modal-overlay').forEach(function(ov){ ov.addEventListener('click', function(ev){ if (ev.target===ov) ov.classList.remove('open'); }); });
    var dlApps=document.createElement('datalist'); dlApps.id='prAppsDl'; dlApps.innerHTML=PR.apps.map(function(a){ return '<option value="'+esc(a.pre.slice(0,-1))+'">'+esc(a.label)+'</option>'; }).join(''); document.body.appendChild(dlApps);
    var dlHdr=document.createElement('datalist'); dlHdr.id='prKnownHdr'; dlHdr.innerHTML=PR.known.map(function(k){ return '<option value="'+esc(k.name)+'">'+esc(k.note.slice(0,60))+'</option>'; }).join(''); document.body.appendChild(dlHdr);
    load();
    })();
    </script>
